322			}
323			if (parsed.hold.until !== undefined) {
324				if (
325					typeof parsed.hold.until !== "string" ||
326					!DATE_RE.test(parsed.hold.until)
327				) {
328					validation(
329						"Work item tasks-axi metadata hold-until must be YYYY-MM-DD",
330					);
331				}
332				hold.until = parsed.hold.until;
333			}
334			meta.hold = hold;
335		}
336		if (parsed.links !== undefined) {
337			if (!Array.isArray(parsed.links)) {
338				validation("Work item tasks-axi metadata links must be an array");
339			}
340			const links = parsed.links.map((value) => {
341				if (
342					!isRecord(value) ||
343					Object.keys(value).some((key) => !["kind", "url"].includes(key)) ||
344					!["pr", "report", "doc"].includes(value.kind as string) ||
345					typeof value.url !== "string"
346				) {
347					validation("Work item tasks-axi metadata link is invalid");
348				}
349				return { kind: value.kind as TaskLink["kind"], url: value.url };
350			});
