357					);
358				}
359				throw error;
360			}
361		}
362		for (const field of ["created", "closed", "pending_closed"] as const) {
363			const value = parsed[field];
364			if (value === undefined) continue;
365			if (typeof value !== "string" || !DATE_RE.test(value)) {
366				validation(`Work item tasks-axi metadata ${field} must be YYYY-MM-DD`);
367			}
368			meta[field] = value;
369		}
370		if (meta.closed && meta.pending_closed) {
371			validation(
372				"Work item tasks-axi metadata cannot contain both closed and pending_closed",
373			);
374		}
375		if (parsed.meta !== undefined) {
376			if (!isRecord(parsed.meta)) {
377				validation("Work item tasks-axi metadata meta must be an object");
378			}
379			meta.meta = parsed.meta;
380		}
381		return meta;
382	}
