384	function relationTargetId(url: string): number | undefined {
385		const match = /\/(\d+)$/.exec(url);
386		return match ? Number(match[1]) : undefined;
387	}
388	
389	function comment(relation: { attributes?: Record<string, unknown> }): string {
390		const value = relation.attributes?.comment;
391		return typeof value === "string" ? value : "";
392	}
393	
394	function normalizedField(field: string, value: unknown): unknown {
395		if (field === F_STATE || field === F_AREA) {
396			return typeof value === "string" ? value.toLowerCase() : value;
397		}
398		if (field === F_TAGS) return parseTags(value).sort();
399		if (field === F_DESCRIPTION) {
400			const description = str(value);
401			return description === undefined ? "" : decodeDescription(description);
402		}
403		return value;
404	}
405	
406	function normalizedRelations(relations: WorkItem["relations"]): string[] {
407		return (relations ?? [])
408			.map((relation) =>
409				JSON.stringify({
410					rel: relation.rel,
411					target: relationTargetId(relation.url) ?? relation.url,
412					comment: comment(relation),
413				}),
414			)
415			.sort((left, right) => left.localeCompare(right));
416	}
417	
418	function requirePatchPostconditions(
419		before: WorkItem,
420		after: WorkItem,
421		ops: JsonPatchOp[],
422	): void {
423		const fields = new Map<string, JsonPatchOp>();
424		const relations = structuredClone(before.relations ?? []);
425		let relationsChanged = false;
426		for (const op of ops) {
427			const field = /^\/fields\/(.+)$/.exec(op.path)?.[1];
428			if (field) {
429				fields.set(field, op);
430				continue;
431			}
432			if (op.path === "/relations/-") {
433				relations.push(op.value as NonNullable<WorkItem["relations"]>[number]);
434				relationsChanged = true;
435				continue;
436			}
437			const relation = /^\/relations\/(\d+)$/.exec(op.path);
438			if (relation && op.op === "remove") {
439				relations.splice(Number(relation[1]), 1);
440				relationsChanged = true;
441			}
442		}
443		for (const [field, op] of fields) {
444			const matches =
445				op.op === "remove"
446					? !Object.hasOwn(after.fields, field)
447					: canonicalEqual(
448							normalizedField(field, after.fields[field]),
449							normalizedField(field, op.value),
450						);

