218		const next: Dep = { type: dep.type, id: depId };
219		if (dep.reason !== undefined) {
220			const reason = dep.reason.trim();
221			if (/[\r\n]/.test(dep.reason)) {
222				validation("Dependency reason must be a single line");
223			}
224			if (reason !== "") next.reason = reason;
225		}
226		return next;
227	}
