229	function dateOnly(value: unknown): string | undefined {
230		return typeof value === "string" && value.length >= 10
231			? value.slice(0, 10)
232			: undefined;
233	}
234	
235	function str(value: unknown): string | undefined {
236		return typeof value === "string" && value !== "" ? value : undefined;
237	}
238	
239	function parseTags(raw: unknown): string[] {
240		return typeof raw === "string"
241			? raw
242					.split(";")
243					.map((tag) => tag.trim())
244					.filter((tag) => tag !== "")
245			: [];
246	}
247	
248	function isRecord(value: unknown): value is Record<string, unknown> {
249		return !!value && typeof value === "object" && !Array.isArray(value);
250	}
251	
252	function parseMeta(raw: unknown): MetaBlob {
253		if (raw == null || (typeof raw === "string" && raw.trim() === "")) {
254			return { v: META_VERSION };
255		}
256		if (typeof raw !== "string") {
257			validation("Work item tasks-axi metadata must be a string");
258		}
259		let parsed: unknown;
260		try {
261			parsed = JSON.parse(raw);
262		} catch {
263			validation("Work item tasks-axi metadata is not valid JSON");
264		}
265		if (!isRecord(parsed)) {
266			validation("Work item tasks-axi metadata must be a JSON object");
267		}
268		const version = parsed.v;
269		if (version !== META_VERSION) {
270			validation(`Unsupported tasks-axi metadata version: ${String(version)}`);
271		}
272		const unknown = Object.keys(parsed).find(
273			(key) =>
274				![
275					"v",
276					"priority",
277					"hold",
278					"links",
279					"created",
280					"closed",
281					"pending_closed",
282					"meta",
283				].includes(key),
284		);
285		if (unknown) validation(`Unknown tasks-axi metadata field: ${unknown}`);
286	
287		const meta: MetaBlob = { v: META_VERSION };
288		if (parsed.priority !== undefined) {
289			if (typeof parsed.priority !== "number") {
290				validation("Work item tasks-axi metadata priority must be a number");
291			}
292			meta.priority = normalizePriority(parsed.priority);
293		}
294		if (parsed.hold !== undefined) {
295			if (!isRecord(parsed.hold)) {
296				validation("Work item tasks-axi metadata hold must be an object");
297			}
298			const unknownHold = Object.keys(parsed.hold).find(
299				(key) => !["reason", "kind", "until"].includes(key),
300			);
301			if (unknownHold) {
302				validation(`Unknown tasks-axi metadata hold field: ${unknownHold}`);
303			}
304			const reason = parsed.hold.reason;
305			if (
306				typeof reason !== "string" ||
307				reason === "" ||
308				reason !== reason.trim() ||
309				/[\r\n]/.test(reason)
310			) {
311				validation("Work item tasks-axi metadata hold reason is invalid");
312			}
313			const hold: Hold = { reason };
314			if (parsed.hold.kind !== undefined) {
315				if (
316					typeof parsed.hold.kind !== "string" ||
317					!HOLD_KINDS.includes(parsed.hold.kind as NonNullable<Hold["kind"]>)
318				) {
319					validation("Work item tasks-axi metadata hold kind is invalid");
320				}
321				hold.kind = parsed.hold.kind as NonNullable<Hold["kind"]>;
322			}
323			if (parsed.hold.until !== undefined) {
324				if (
325					typeof parsed.hold.until !== "string" ||
326					!DATE_RE.test(parsed.hold.until)
327				) {
328					validation(
329						"Work item tasks-axi metadata hold-until must be YYYY-MM-DD",
330					);
331				}
332				hold.until = parsed.hold.until;
333			}
334			meta.hold = hold;
335		}
336		if (parsed.links !== undefined) {
337			if (!Array.isArray(parsed.links)) {
338				validation("Work item tasks-axi metadata links must be an array");
339			}
340			const links = parsed.links.map((value) => {
341				if (
342					!isRecord(value) ||
343					Object.keys(value).some((key) => !["kind", "url"].includes(key)) ||
344					!["pr", "report", "doc"].includes(value.kind as string) ||
345					typeof value.url !== "string"
346				) {
347					validation("Work item tasks-axi metadata link is invalid");
348				}
349				return { kind: value.kind as TaskLink["kind"], url: value.url };
350			});
351			try {
352				meta.links = normalizeTypedLinks(links);
353			} catch (error) {
354				if (error instanceof AxiError) {
355					validation(
356						`Work item tasks-axi metadata link is invalid: ${error.message}`,
357					);
358				}
359				throw error;
360			}
361		}
362		for (const field of ["created", "closed", "pending_closed"] as const) {
363			const value = parsed[field];
364			if (value === undefined) continue;
365			if (typeof value !== "string" || !DATE_RE.test(value)) {
366				validation(`Work item tasks-axi metadata ${field} must be YYYY-MM-DD`);
367			}
368			meta[field] = value;
369		}
370		if (meta.closed && meta.pending_closed) {
371			validation(
372				"Work item tasks-axi metadata cannot contain both closed and pending_closed",
373			);
374		}
375		if (parsed.meta !== undefined) {
376			if (!isRecord(parsed.meta)) {
377				validation("Work item tasks-axi metadata meta must be an object");
378			}
379			meta.meta = parsed.meta;
380		}
381		return meta;
382	}
383	
384	function relationTargetId(url: string): number | undefined {
385		const match = /\/(\d+)$/.exec(url);
386		return match ? Number(match[1]) : undefined;
387	}
388	
389	function comment(relation: { attributes?: Record<string, unknown> }): string {
390		const value = relation.attributes?.comment;
391		return typeof value === "string" ? value : "";
392	}
393	
394	function normalizedField(field: string, value: unknown): unknown {
395		if (field === F_STATE || field === F_AREA) {
396			return typeof value === "string" ? value.toLowerCase() : value;
397		}
398		if (field === F_TAGS) return parseTags(value).sort();
399		if (field === F_DESCRIPTION) {
400			const description = str(value);
401			return description === undefined ? "" : decodeDescription(description);
402		}
403		return value;
404	}
405	
406	function normalizedRelations(relations: WorkItem["relations"]): string[] {
407		return (relations ?? [])
408			.map((relation) =>
409				JSON.stringify({
410					rel: relation.rel,
411					target: relationTargetId(relation.url) ?? relation.url,
412					comment: comment(relation),
413				}),
414			)
415			.sort((left, right) => left.localeCompare(right));
416	}
417	
418	function requirePatchPostconditions(
419		before: WorkItem,
420		after: WorkItem,
421		ops: JsonPatchOp[],
422	): void {
423		const fields = new Map<string, JsonPatchOp>();
424		const relations = structuredClone(before.relations ?? []);
425		let relationsChanged = false;
426		for (const op of ops) {
427			const field = /^\/fields\/(.+)$/.exec(op.path)?.[1];
428			if (field) {
429				fields.set(field, op);
430				continue;
431			}
432			if (op.path === "/relations/-") {
433				relations.push(op.value as NonNullable<WorkItem["relations"]>[number]);
434				relationsChanged = true;
435				continue;
436			}
437			const relation = /^\/relations\/(\d+)$/.exec(op.path);
438			if (relation && op.op === "remove") {
439				relations.splice(Number(relation[1]), 1);
440				relationsChanged = true;
441			}
442		}
443		for (const [field, op] of fields) {
444			const matches =
445				op.op === "remove"
446					? !Object.hasOwn(after.fields, field)
447					: canonicalEqual(
448							normalizedField(field, after.fields[field]),
449							normalizedField(field, op.value),
450						);

text:
451			if (!matches) {
452				throw new AxiError(
453					`Work item ${after.id} did not persist ${field}`,
454					"CONFLICT",
455				);
456			}
457		}
458		if (
459			relationsChanged &&
460			!canonicalEqual(
461				normalizedRelations(after.relations),
462				normalizedRelations(relations),
463			)
464		) {
465			throw new AxiError(
466				`Work item ${after.id} did not persist its relation changes`,
467				"CONFLICT",
468			);
469		}
470	}
471	
472	function ownedRelationMarkerOwner(
473		relation: { rel: string; attributes?: Record<string, unknown> },
474		relationType: string,
475		marker: string,
476	): string | undefined {
477		if (relation.rel !== relationType) return undefined;
478		const prefix = `${marker}:`;
479		const text = comment(relation);
480		if (!text.startsWith(prefix)) return undefined;
481		return text.slice(prefix.length).split(":", 1)[0];
482	}
483	
484	function relationMarkerOwner(relation: {
485		rel: string;
486		attributes?: Record<string, unknown>;
487	}): string | undefined {
488		return (
489			ownedRelationMarkerOwner(relation, REL_PARENT, PARENT_MARKER) ??
490			ownedRelationMarkerOwner(relation, REL_RELATED, DISCOVERED_MARKER)
491		);
492	}
493	
494	function requireOwnedRelationEndpoints(
495		items: WorkItem[],
496		slugs: Map<number, string>,
497	): void {
498		for (const item of items) {
499			const ownerId = slugs.get(item.id);
500			if (!ownerId) validation(`Work item ${item.id} has no tasks-axi id`);
501			for (const relation of item.relations ?? []) {
502				const markerOwner = relationMarkerOwner(relation);
503				if (markerOwner === undefined) continue;
504				const targetId = relationTargetId(relation.url);
505				const targetSlug =
506					targetId === undefined ? undefined : slugs.get(targetId);
507				if (!targetSlug) {
508					validation(
509						`Work item ${item.id} has an unavailable owned relation target`,
510					);
511				}
512				if (markerOwner !== ownerId && markerOwner !== targetSlug) {
513					throw new AxiError(
514						`Work item ${item.id} has a stale tasks-axi relation marker for "${markerOwner}"; its endpoints are "${ownerId}" and "${targetSlug}"`,
515						"CONFLICT",
516						["Repair or remove the stale relation in Azure DevOps"],
517					);
518				}
519			}
520		}
521	}
522	
523	function ownedRelationReason(
524		relation: { rel: string; attributes?: Record<string, unknown> },
525		relationType: string,
526		marker: string,
527		ownerId: string,
528	): string | undefined {
529		if (ownedRelationMarkerOwner(relation, relationType, marker) !== ownerId) {
530			return undefined;
531		}
532		const text = comment(relation);
533		const ownerMarker = `${marker}:${ownerId}`;
534		if (text === ownerMarker) return "";
535		return text.startsWith(`${ownerMarker}:`)
536			? text.slice(ownerMarker.length + 1)
537			: undefined;
538	}
539	
540	function discoveredReason(
541		relation: { rel: string; attributes?: Record<string, unknown> },
542		ownerId: string,
543	): string | undefined {
544		return ownedRelationReason(relation, REL_RELATED, DISCOVERED_MARKER, ownerId);
545	}
546	
547	function parentReason(
548		relation: { rel: string; attributes?: Record<string, unknown> },
549		ownerId: string,
550	): string | undefined {
551		return ownedRelationReason(relation, REL_PARENT, PARENT_MARKER, ownerId);
552	}
