554	export class AdoStore implements Store {
555		private readonly client: AdoClient;
556		private readonly project: string;
557		private readonly area?: string;
558		private readonly workItemType: string;
559		private readonly idField: string;
560		private readonly metaField: string;
561		private readonly followupField: string;
562		private readonly states: Record<State, string[]>;
563		private readonly now: () => string;
