565		constructor(options: AdoStoreOptions) {
566			this.client = options.client;
567			this.project = options.project;
568			if (options.area) this.area = options.area;
569			this.workItemType = options.workItemType;
570			this.idField = options.idField;
571			this.metaField = options.metaField;
572			this.followupField = options.followupField;
573			this.states = options.states;
