576	
577		capabilities(): Capabilities {
578			return {
579				backend: "ado",
580				deps: true,
581				// No hard prune and no canonical re-render: ADO owns its own storage.
582				prune: false,
583				comments: false,
584				fullTextSearch: false,
585				realtimeSync: false,
586				customStates: false,
587				serverMintsIds: false,
588				publicFollowups: true,
589				fileMoves: false,
590			};
591		}
592	
593		// ---------------------------------------------------------------------
594		// State mapping
595		// ---------------------------------------------------------------------
596	
597		private adoState(state: State): string {
598			return this.states[state][0];
599		}
600	
601		private toState(adoState: string): State {
602			const normalized = adoState.toLowerCase();
603			for (const state of ["queued", "in_flight", "done"] as State[]) {
604				if (
605					this.states[state].some((name) => name.toLowerCase() === normalized)
606				) {
607					return state;
608				}
609			}
610			return validation(
611				`Azure DevOps state "${adoState}" is not mapped to a tasks-axi state`,
612				[
613					"Add it to `[ado] state_queued` / `state_in_flight` / `state_done` in .tasks.toml",
614				],
615			);
616		}
617	
618		// ---------------------------------------------------------------------
619		// Read
620		// ---------------------------------------------------------------------
621	
622		private wiql(where: string[], area = this.area): string {
623			const clauses = [
624				`[System.TeamProject] = '${sq(this.project)}'`,
625				`[System.WorkItemType] = '${sq(this.workItemType)}'`,
626				`[${this.idField}] <> ''`,
627				...(area ? [`[System.AreaPath] UNDER '${sq(area)}'`] : []),
628				...where,
629			];
630			return `SELECT [System.Id] FROM WorkItems WHERE ${clauses.join(" AND ")}`;
631		}
632	
633		/** Resolve a tasks-axi slug id to its work item id. */
634		private async findWorkItemId(id: string): Promise<number | undefined> {
635			const ids = await this.client.queryIds(
636				this.wiql([`[${this.idField}] = '${sq(id)}'`]),
637			);
638			if (ids.length > 1) {
639				throw new AxiError(
640					`Task "${id}" matches multiple Azure DevOps work items`,
641					"CONFLICT",
642					[`Make ${this.idField} unique before retrying`],
643				);
644			}
645			return ids[0];
646		}
647	
648		private isAreaInScope(areaPath: string | undefined): boolean {
649			if (!this.area) return true;
650			const area = areaPath?.toLowerCase();
651			const expected = this.area.toLowerCase();
652			return area === expected || area?.startsWith(`${expected}\\`) === true;
653		}
654	
655		private requireInProject(item: WorkItem): void {
656			if (
657				str(item.fields[F_PROJECT])?.toLowerCase() !== this.project.toLowerCase()
658			) {
659				throw new AxiError(
660					`Work item ${item.id} left the configured Azure DevOps project while it was being loaded`,
661					"CONFLICT",
662					["Retry the command after checking the work item's Team Project"],
663				);
664			}
665		}
666	
667		private requireInProjectAndType(item: WorkItem): void {
668			this.requireInProject(item);
669			const workItemType = str(item.fields[F_WORK_ITEM_TYPE]);
670			if (workItemType?.toLowerCase() !== this.workItemType.toLowerCase()) {
671				throw new AxiError(
672					`Work item ${item.id} has Azure DevOps type "${workItemType ?? ""}", expected "${this.workItemType}"`,
673					"CONFLICT",
674					["Retry the command after checking the work item's Work Item Type"],
675				);
676			}
677		}
678	
679		private requireInScope(item: WorkItem): void {
680			this.requireInProjectAndType(item);
681			if (!this.isAreaInScope(str(item.fields[F_AREA]))) {
682				throw new AxiError(
683					`Work item ${item.id} left the configured Azure DevOps area while it was being loaded`,
684					"CONFLICT",
685					["Retry the command after checking the work item's Area Path"],
686				);
687			}
688		}
689	
690		private requireMutationResult(
691			item: WorkItem,
692			expectedId: string,
693			expectedArea?: string,
694		): void {
695			if (expectedArea === undefined) {
696				this.requireInScope(item);
697			} else {
698				this.requireInProjectAndType(item);
699				if (
700					str(item.fields[F_AREA])?.toLowerCase() !== expectedArea.toLowerCase()
701				) {
702					throw new AxiError(
703						`Work item ${item.id} did not land in Azure DevOps area "${expectedArea}"`,
704						"CONFLICT",
705					);
706				}
707			}
708			if (this.taskId(item) !== expectedId) {
709				throw new AxiError(
710					`Work item ${item.id} returned an unexpected ${this.idField} value`,
711					"CONFLICT",
712				);
713			}
714		}
715	
716		private taskId(item: WorkItem): string | undefined {
717			const id = str(item.fields[this.idField]);
718			if (!id) return undefined;
719			try {
720				return validateId(id);
721			} catch {
722				validation(
723					`Work item ${item.id} has invalid ${this.idField} value ${JSON.stringify(id)}`,
724				);
725			}
726		}
727	
728		private async loadItem(id: string): Promise<WorkItem | undefined> {
729			const workItemId = await this.findWorkItemId(id);
730			if (workItemId === undefined) return undefined;
731			const item = await this.client.get(workItemId);
732			if (!item) return undefined;
733			if (this.taskId(item) !== id) {
734				throw new AxiError(
735					`Task "${id}" changed identity while it was being loaded`,
736					"CONFLICT",
737					["Retry the command after checking the Azure DevOps join field"],
738				);
739			}
740			this.requireInScope(item);
741			return item;
742		}
743	
744		private async requireItem(id: string): Promise<WorkItem> {
745			const item = await this.loadItem(id);
746			if (!item) throw new AxiError(`Task "${id}" not found`, "NOT_FOUND");
747			return item;
748		}
749	
750		/**
751		 * Map linked work item ids to their tasks-axi slugs. Relations point at
752		 * numeric ids, so one batched read turns them back into join keys.
753		 */
754		private async slugMap(items: WorkItem[]): Promise<Map<number, string>> {
755			const known = new Map<number, string>();
756			const workItemBySlug = new Map<string, number>();
757			const remember = (item: WorkItem) => {
758				const slug = this.taskId(item);
759				if (!slug) {
760					validation(`Work item ${item.id} has no ${this.idField} value`);
761				}
762				const key = slug.toLowerCase();
763				const existing = workItemBySlug.get(key);
764				if (existing !== undefined && existing !== item.id) {
765					throw new AxiError(
766						`Task "${slug}" matches multiple Azure DevOps work items`,
767						"CONFLICT",
768						[`Make ${this.idField} unique before retrying`],
769					);
770				}
771				known.set(item.id, slug);
772				workItemBySlug.set(key, item.id);
773			};
774			for (const item of items) remember(item);
775			const missing = new Map<number, boolean>();
776			for (const item of items) {
777				for (const relation of item.relations ?? []) {
778					const forwardDependency = relation.rel === REL_BLOCKS;
779					const markerOwner = relationMarkerOwner(relation);
780					const supported =
781						relation.rel === REL_BLOCKED_BY ||
782						forwardDependency ||
783						markerOwner !== undefined;
784					const target = supported ? relationTargetId(relation.url) : undefined;
785					if (supported && target === undefined) {
786						validation(
787							`Work item ${item.id} has a malformed ${relation.rel} relation target`,
788						);
789					}
790					if (target !== undefined && !known.has(target)) {
791						missing.set(
792							target,
793							(missing.get(target) ?? false) || !forwardDependency,
794						);
795					}
796				}
797			}
798			if (missing.size > 0) {
799				for (const item of await this.client.getMany([...missing.keys()])) {
800					if (!missing.get(item.id) && !this.taskId(item)) continue;
801					this.requireInScope(item);
802					remember(item);
803				}
804			}
805			requireOwnedRelationEndpoints(items, known);
806			return known;
807		}
808	
809		private toTask(item: WorkItem, slugs: Map<number, string>): Task {
810			const fields = item.fields;
811			const id = this.taskId(item);
812			if (!id) {
813				validation(`Work item ${item.id} has no ${this.idField} value`);
814			}
815			const rawMeta = fields[this.metaField];
816			const meta = parseMeta(rawMeta);
817			const tags = parseTags(fields[F_TAGS]);
818			const task: Task = {
819				id,
820				title: str(fields[F_TITLE]) ?? "",
821				state: this.toState(String(fields[F_STATE] ?? "")),
822				links: meta.links ?? [],
823				deps: this.depsOf(item, slugs),
824			};
825			const kind = tagValue(tags, "kind");
826			const repo = tagValue(tags, "repo");
827			if (kind) task.kind = kind;
828			if (repo) task.repo = repo;
829			const rawBody = str(fields[F_DESCRIPTION]);
830			const body = rawBody === undefined ? undefined : decodeDescription(rawBody);
831			if (body) task.body = body;
832			if (meta.hold) task.hold = meta.hold;
833			if (meta.priority !== undefined) task.priority = meta.priority;
834			const metaMissing =
835				rawMeta == null || (typeof rawMeta === "string" && rawMeta.trim() === "");
836			const created =
837				meta.created ?? (metaMissing ? dateOnly(fields[F_CREATED]) : undefined);
838			if (created) task.created = created;
839			const updated = dateOnly(fields[F_CHANGED]);
840			if (updated) task.updated = updated;
841			// An ADO-only reopen/re-close between reads retains the last tasks-axi close date.
842			const closed = meta.closed ?? meta.pending_closed;
843			if (closed && task.state === "done") task.closed = closed;
844			const followup = str(fields[this.followupField]);
845			const hasFollowup = followup !== undefined && followup.trim() !== "";
846			if ((kind === PUBLIC_FOLLOWUP_KIND) !== hasFollowup) {
847				validation(
848					"kind=public-followup and typed public_followup data must be present together",
849				);
850			}
851			if (hasFollowup) {
852				if (meta.hold) {
853					validation("Public-followup obligations cannot use dispatch holds");
854				}
