472	function ownedRelationMarkerOwner(
473		relation: { rel: string; attributes?: Record<string, unknown> },
474		relationType: string,
475		marker: string,
476	): string | undefined {
477		if (relation.rel !== relationType) return undefined;
478		const prefix = `${marker}:`;
479		const text = comment(relation);
480		if (!text.startsWith(prefix)) return undefined;
481		return text.slice(prefix.length).split(":", 1)[0];
482	}
