484	function relationMarkerOwner(relation: {
485		rel: string;
486		attributes?: Record<string, unknown>;
487	}): string | undefined {
488		return (
489			ownedRelationMarkerOwner(relation, REL_PARENT, PARENT_MARKER) ??
490			ownedRelationMarkerOwner(relation, REL_RELATED, DISCOVERED_MARKER)
491		);
492	}
