494	function requireOwnedRelationEndpoints(
495		items: WorkItem[],
496		slugs: Map<number, string>,
497	): void {
498		for (const item of items) {
499			const ownerId = slugs.get(item.id);
500			if (!ownerId) validation(`Work item ${item.id} has no tasks-axi id`);
501			for (const relation of item.relations ?? []) {
502				const markerOwner = relationMarkerOwner(relation);
503				if (markerOwner === undefined) continue;
504				const targetId = relationTargetId(relation.url);
505				const targetSlug =
506					targetId === undefined ? undefined : slugs.get(targetId);
507				if (!targetSlug) {
508					validation(
509						`Work item ${item.id} has an unavailable owned relation target`,
510					);
511				}
512				if (markerOwner !== ownerId && markerOwner !== targetSlug) {
513					throw new AxiError(
514						`Work item ${item.id} has a stale tasks-axi relation marker for "${markerOwner}"; its endpoints are "${ownerId}" and "${targetSlug}"`,
515						"CONFLICT",
516						["Repair or remove the stale relation in Azure DevOps"],
517					);
518				}
519			}
520		}
521	}
522	
523	function ownedRelationReason(
524		relation: { rel: string; attributes?: Record<string, unknown> },
525		relationType: string,
526		marker: string,
527		ownerId: string,
528	): string | undefined {
529		if (ownedRelationMarkerOwner(relation, relationType, marker) !== ownerId) {
530			return undefined;
531		}
532		const text = comment(relation);
533		const ownerMarker = `${marker}:${ownerId}`;
534		if (text === ownerMarker) return "";
535		return text.startsWith(`${ownerMarker}:`)
536			? text.slice(ownerMarker.length + 1)
537			: undefined;
538	}
