540	function discoveredReason(
541		relation: { rel: string; attributes?: Record<string, unknown> },
542		ownerId: string,
543	): string | undefined {
544		return ownedRelationReason(relation, REL_RELATED, DISCOVERED_MARKER, ownerId);
545	}
