  1212	    }
  1213	  }
  1214	  if (next.revision !== previous.revision + 1) {
  1215	    validation("public_followup revision must increase by exactly one");
  1216	  }
  1217	  if (
  1218	    !DELIVERY_TRANSITIONS[previous.delivery.state].includes(next.delivery.state)
  1219	  ) {
