  1230	  ) {
  1231	    validation("public_followup delivery payload_digest cannot change");
  1232	  }
  1233	  for (const previousRelation of previous.work_relations) {
  1234	    const nextRelation = next.work_relations.find(
  1235	      (relation) => relation.relation_id === previousRelation.relation_id,
  1236	    );
  1237	    if (!nextRelation) {
  1238	      validation(
  1239	        `public_followup relation ${previousRelation.relation_id} cannot be removed`,
  1240	      );
  1241	    }
  1242	    if (
  1243	      !canonicalEqual(
  1244	        immutableRelation(previousRelation),
  1245	        immutableRelation(nextRelation),
  1246	      )
  1247	    ) {
  1248	      validation(
  1249	        `public_followup relation ${previousRelation.relation_id} identity cannot change`,
  1250	      );
  1251	    }
  1252	    const oldIds = previousRelation.accepted_event_ids;
  1253	    if (
  1254	      !oldIds.every(
  1255	        (event, index) => nextRelation.accepted_event_ids[index] === event,
  1256	      )
  1257	    ) {
  1258	      validation(
  1259	        `public_followup relation ${previousRelation.relation_id} events are append-only`,
  1260	      );
  1261	    }
  1262	    if (
  1263	      !previousRelation.accepted_events.every((event, index) =>
  1264	        canonicalEqual(event, nextRelation.accepted_events[index]),
  1265	      )
  1266	    ) {
  1267	      validation(
  1268	        `public_followup relation ${previousRelation.relation_id} event data cannot change`,
  1269	      );
  1270	    }
  1271	    if (
  1272	      previousRelation.state === "landed" &&
  1273	      (nextRelation.state !== "landed" ||
  1274	        nextRelation.accepted_event_ids.length !== oldIds.length)
  1275	    ) {
  1276	      validation(
  1277	        `public_followup landed relation ${previousRelation.relation_id} is immutable`,
  1278	      );
  1279	    }
  1280	    if (
  1281	      previousRelation.state === "superseded" &&
  1282	      (nextRelation.state !== "superseded" ||
  1283	        nextRelation.accepted_event_ids.length !== oldIds.length)
  1284	    ) {
  1285	      validation(
  1286	        `public_followup superseded relation ${previousRelation.relation_id} is immutable`,
  1287	      );
  1288	    }
  1289	    if (
  1290	      previousRelation.state === "failed" &&
  1291	      !["failed", "superseded"].includes(nextRelation.state)
  1292	    ) {
  1293	      validation(
  1294	        `public_followup failed relation ${previousRelation.relation_id} cannot regress`,
  1295	      );
  1296	    }
  1297	    if (
  1298	      previousRelation.successor_relation_id !== null &&
  1299	      nextRelation.successor_relation_id !==
  1300	        previousRelation.successor_relation_id
  1301	    ) {
  1302	      validation(
