  1	import { AxiError } from "../../src/errors.js";
  2	import type {
  3		AdoClient,
  4		JsonPatchOp,
  5		WorkItem,
  6		WorkItemRelation,
  7	} from "../../src/backends/ado-client.js";
  8	
  9	/**
 10	 * In-memory stand-in for the Azure DevOps REST surface: enough JSON-patch and
 11	 * WIQL semantics to drive the store without touching a live project.
 12	 */
 13	export class FakeAdoClient implements AdoClient {
 14		readonly items = new Map<number, WorkItem>();
 15		private nextId = 1;
 16		/** Every mutating call, so tests can assert the wire shape. */
 17		readonly calls: { kind: string; id?: number; patch?: JsonPatchOp[] }[] = [];
 18	
 19		constructor(
 20			private readonly idField = "Custom.TasksAxiId",
 21			private readonly project = "Internal",
 22		) {}
 23	
 24		workItemUrl(id: number): string {
 25			return `https://dev.azure.com/org/_apis/wit/workItems/${id}`;
 26		}
 27	
 28		async queryIds(wiql: string): Promise<number[]> {
 29			const byId = new RegExp(
 30				`\\[${escapeRegExp(this.idField)}\\] = '([^']*)'`,
 31			).exec(wiql);
 32			const project = /\[System\.TeamProject\] = '([^']*)'/.exec(wiql);
 33			const workItemType = /\[System\.WorkItemType\] = '([^']*)'/.exec(wiql);
 34			const area = /UNDER '([^']*)'/.exec(wiql);
 35			return [...this.items.values()]
 36				.filter((item) => {
 37					const slug = item.fields[this.idField];
 38					if (typeof slug !== "string" || slug === "") return false;
 39					if (
 40						byId &&
 41						slug.toLowerCase() !== byId[1].replace(/''/g, "'").toLowerCase()
 42					) {
 43						return false;
 44					}
 45					if (
 46						project &&
 47						item.fields["System.TeamProject"] !== project[1].replace(/''/g, "'")
 48					) {
 49						return false;
 50					}
 51					if (
 52						workItemType &&
 53						String(item.fields["System.WorkItemType"] ?? "").toLowerCase() !==
 54							workItemType[1].replace(/''/g, "'").toLowerCase()
 55					) {
 56						return false;
 57					}
 58					if (area) {
 59						const path = String(item.fields["System.AreaPath"] ?? "");
 60						if (path !== area[1] && !path.startsWith(`${area[1]}\\`))
 61							return false;
 62					}
 63					return true;
 64				})
 65				.map((item) => item.id);
 66		}
 67	
 68		async getMany(ids: number[]): Promise<WorkItem[]> {
 69			const items = ids.flatMap((id) => {
 70				const item = this.items.get(id);
 71				return item ? [item] : [];
 72			});
 73			const expected = new Set(ids);
 74			const returned = new Set(items.map((item) => item.id));
 75			if (
 76				items.length !== expected.size ||
 77				returned.size !== items.length ||
 78				[...expected].some((id) => !returned.has(id)) ||
 79				[...returned].some((id) => !expected.has(id))
 80			) {
 81				throw new AxiError(
 82					`Azure DevOps batch read returned ids [${[...returned].join(", ")}], expected [${[...expected].join(", ")}]`,
 83					"CONFLICT",
 84				);
 85			}
 86			return items.map(clone);
 87		}
 88	
 89		async get(id: number): Promise<WorkItem | null> {
 90			const item = this.items.get(id);
 91			return item ? clone(item) : null;
 92		}
 93	
 94		async create(type: string, patch: JsonPatchOp[]): Promise<WorkItem> {
 95			const item: WorkItem = {
 96				id: this.nextId++,
 97				rev: 1,
 98				fields: {
