   428	  private insert(section: Section, entry: TaskEntry, atTop: boolean): void {
   429	    if (atTop) {
   430	      section.entries.unshift(entry);
   431	      return;
   432	    }
   433	    // Insert after the last content entry, before any trailing blank lines.
   434	    let idx = section.entries.length;
   435	    while (idx > 0) {
   436	      const prev = section.entries[idx - 1];
   437	      if (prev.kind === "raw" && prev.lines.every((l) => l.trim() === "")) {
   438	        idx--;
   439	      } else {
   440	        break;
   441	      }
   442	    }
   443	    section.entries.splice(idx, 0, entry);
   444	  }
