  1	import { execFile } from "node:child_process";
  2	import { promisify } from "node:util";
  3	import { AxiError } from "../errors.js";
  4	
  5	/**
  6	 * Thin Azure DevOps REST surface used by the ADO backend (report §8 P3 seam).
  7	 *
  8	 * The store only ever talks to the `AdoClient` interface, so tests drive it
  9	 * with an in-memory fake and the hot path stays direct REST — `ado-axi` is a
 10	 * side tool, never a shell-out per list.
 11	 */
 12	
 13	const execFileAsync = promisify(execFile);
 14	
 15	/** Azure DevOps resource id `az` uses when minting an ADO access token. */
 16	export const ADO_RESOURCE = "499b84ac-1321-427f-aa17-267ca6975798";
 17	
 18	/** PAT env vars, first non-empty wins (same order as ado-axi). */
 19	export const PAT_ENV_VARS = [
 20		"TASKS_AXI_ADO_PAT",
 21		"ADO_PAT",
 22		"AZURE_DEVOPS_EXT_PAT",
 23		"AZURE_DEVOPS_PAT",
 24	];
 25	
 26	const API_VERSION = "7.1";
 27	const DEFAULT_TIMEOUT_MS = 30_000;
 28	const DEFINITIVE_ADO_REJECTIONS = new WeakSet<Error>();
 29	
 30	function definitive<T>(error: T): T {
 31		if (error instanceof Error) DEFINITIVE_ADO_REJECTIONS.add(error);
 32		return error;
 33	}
 34	
 35	export function isDefinitiveAdoRejection(error: unknown): boolean {
 36		return error instanceof Error && DEFINITIVE_ADO_REJECTIONS.has(error);
 37	}
 38	
 39	export interface WorkItemRelation {
 40		rel: string;
 41		url: string;
 42		attributes?: Record<string, unknown>;
 43	}
 44	
 45	export interface WorkItem {
 46		id: number;
 47		rev?: number;
 48		fields: Record<string, unknown>;
 49		relations?: WorkItemRelation[];
 50	}
 51	
 52	export interface JsonPatchOp {
 53		op: "add" | "replace" | "remove" | "test";
 54		path: string;
 55		value?: unknown;
 56	}
 57	
 58	/** The narrow ADO surface the store depends on. */
 59	export interface AdoClient {
 60		/** Run a WIQL query and return the matching work item ids. */
 61		queryIds(wiql: string): Promise<number[]>;
 62		/** Batch-read work items including relations. */
 63		getMany(ids: number[]): Promise<WorkItem[]>;
 64		get(id: number): Promise<WorkItem | null>;
 65		create(type: string, patch: JsonPatchOp[]): Promise<WorkItem>;
 66		update(id: number, patch: JsonPatchOp[]): Promise<WorkItem>;
 67		/** Send a work item to the ADO recycle bin (recoverable, never a hard delete). */
 68		remove(id: number): Promise<void>;
 69		/** The canonical `_apis/wit/workItems/<id>` url used in relation values. */
 70		workItemUrl(id: number): string;
 71	}
 72	
 73	export interface AdoRestClientOptions {
 74		org: string;
 75		project: string;
 76		host?: string;
 77		env?: NodeJS.ProcessEnv;
 78		platform?: NodeJS.Platform;
 79		fetchImpl?: typeof fetch;
 80		timeoutMs?: number;
 81	}
 82	
 83	function enc(value: string): string {
 84		return encodeURIComponent(value);
 85	}
 86	
 87	/** Personal access token from the environment, or undefined. */
 88	export function patFromEnv(env: NodeJS.ProcessEnv): string | undefined {
 89		for (const name of PAT_ENV_VARS) {
 90			const value = env[name];
 91			if (value && value.trim() !== "") return value.trim();
 92		}
 93		return undefined;
 94	}
 95	
 96	/** Live REST client: PAT Basic auth, falling back to an `az` bearer token. */
 97	export class AdoRestClient implements AdoClient {
 98		private readonly org: string;
 99		private readonly project: string;
100		private readonly host: string;
101		private readonly env: NodeJS.ProcessEnv;
102		private readonly platform: NodeJS.Platform;
103		private readonly fetchImpl: typeof fetch;
104		private readonly timeoutMs: number;
105		private authHeader?: string;
106	
107		constructor(options: AdoRestClientOptions) {
108			this.org = options.org;
109			this.project = options.project;
110			this.host = options.host ?? "dev.azure.com";
111			this.env = options.env ?? process.env;
112			this.platform = options.platform ?? process.platform;
113			this.fetchImpl = options.fetchImpl ?? globalThis.fetch.bind(globalThis);
114			this.timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
115		}
116	
117		private async authorization(): Promise<string> {
118			if (this.authHeader) return this.authHeader;
119			const pat = patFromEnv(this.env);
120			if (pat) {
121				this.authHeader = `Basic ${Buffer.from(`:${pat}`).toString("base64")}`;
122				return this.authHeader;
123			}
124			let stdout: string;
125			const args = [
126				"account",
127				"get-access-token",
128				"--resource",
129				ADO_RESOURCE,
130				"-o",
131				"json",
132			];
133			const windows = this.platform === "win32";
134			try {
135				({ stdout } = await execFileAsync(
136					windows ? this.env.ComSpec || "cmd.exe" : "az",
137					windows ? ["/d", "/s", "/c", "az.cmd", ...args] : args,
138					{ env: this.env, timeout: this.timeoutMs },
139				));
140			} catch (error) {
141				throw new AxiError(
142					`No Azure DevOps credential: set ${PAT_ENV_VARS[0]} or sign in with \`az login\` (${error instanceof Error ? error.message : String(error)})`,
143					"VALIDATION_ERROR",
144					[`export ${PAT_ENV_VARS[0]}=<pat>`, "az login"],
145				);
146			}
147			const tokenResponse = parseJson<unknown>(stdout, "az access-token output");
148			if (
149				!isRecord(tokenResponse) ||
150				typeof tokenResponse.accessToken !== "string" ||
151				tokenResponse.accessToken.trim() === ""
152			) {
153				throw new AxiError(
154					"az returned no valid access token for Azure DevOps",
155					"VALIDATION_ERROR",
156				);
157			}
158			this.authHeader = `Bearer ${tokenResponse.accessToken.trim()}`;
159			return this.authHeader;
160		}
161	
162		private async request<T>(
163			path: string,
164			options: {
165				method?: string;
166				query?: Record<string, string | number | undefined>;
167				body?: unknown;
168				contentType?: string;
169			} = {},
170		): Promise<T> {
171			const query: Record<string, string> = { "api-version": API_VERSION };
172			for (const [key, value] of Object.entries(options.query ?? {})) {
173				if (value !== undefined && value !== "") query[key] = String(value);
174			}
175			const qs = new URLSearchParams(query).toString();
176			const url = `https://${this.host}/${enc(this.org)}${path}?${qs}`;
177			let authorization: string;
178			try {
179				authorization = await this.authorization();
180			} catch (error) {
181				throw definitive(error);
182			}
183			const signal = AbortSignal.timeout(this.timeoutMs);
184			let response: Response;
185			let text: string;
186			try {
187				response = await this.fetchImpl(url, {
188					method: options.method ?? "GET",
189					headers: {
190						Authorization: authorization,
191						Accept: "application/json",
192						...(options.body === undefined
193							? {}
194							: { "Content-Type": options.contentType ?? "application/json" }),
195					},
196					signal,
197					...(options.body === undefined
198						? {}
199						: { body: JSON.stringify(options.body) }),
200				});
201				text = await response.text();
202			} catch (error) {
203				if (signal.aborted) {
204					throw new AxiError(
205						`Azure DevOps request timed out after ${this.timeoutMs}ms`,
206						"UNKNOWN",
207					);
208				}
209				throw error;
210			}
211			if (!response.ok) {
212				throw adoError(response.status, text);
213			}
214			// Azure DevOps answers an unauthenticated REST call with 203 and an HTML
215			// sign-in page instead of a 401, so `response.ok` is true and the body is
216			// not JSON. Caught here, where every request routes through, so a bad or
217			// missing credential reads as an auth failure rather than a parse error.
218			if (response.status === 203 || /^\s*</.test(text)) {
219				throw definitive(
220					new AxiError(
221						"Azure DevOps rejected the credential (it returned a sign-in page)",
222						"VALIDATION_ERROR",
223						[
224							`export ${PAT_ENV_VARS[0]}=<pat> with Work Items (read & write) scope`,
225							"Or run `az login` for a bearer token",
226							`Check the org is spelled correctly: https://${this.host}/${enc(this.org)}`,
227						],
228					),
229				);
230			}
231			return (
232				text ? parseJson<T>(text, "Azure DevOps response") : undefined
233			) as T;
234		}
235	
236		async queryIds(wiql: string): Promise<number[]> {
237			const data = await this.request<unknown>(
238				`/${enc(this.project)}/_apis/wit/wiql`,
239				{ method: "POST", body: { query: wiql } },
240			);
241			let workItems: unknown;
242			if (typeof data === "object" && data !== null && "workItems" in data) {
243				workItems = data.workItems;
244			}
245			if (
246				!Array.isArray(workItems) ||
247				workItems.some(
248					(item) =>
249						typeof item !== "object" ||
250						item === null ||
251						!("id" in item) ||
252						typeof item.id !== "number" ||
253						!Number.isSafeInteger(item.id) ||
254						item.id <= 0,
255				)
256			) {
257				throw new AxiError(
258					"Azure DevOps WIQL response did not contain a valid workItems array",
259					"UNKNOWN",
260				);
261			}
262			return workItems.map((item) => (item as { id: number }).id);
263		}
