107		constructor(options: AdoRestClientOptions) {
108			this.org = options.org;
109			this.project = options.project;
110			this.host = options.host ?? "dev.azure.com";
111			this.env = options.env ?? process.env;
112			this.platform = options.platform ?? process.platform;
113			this.fetchImpl = options.fetchImpl ?? globalThis.fetch.bind(globalThis);
