117		private async authorization(): Promise<string> {
118			if (this.authHeader) return this.authHeader;
119			const pat = patFromEnv(this.env);
120			if (pat) {
121				this.authHeader = `Basic ${Buffer.from(`:${pat}`).toString("base64")}`;
122				return this.authHeader;
123			}
124			let stdout: string;
125			const args = [
126				"account",
127				"get-access-token",
128				"--resource",
129				ADO_RESOURCE,
130				"-o",
131				"json",
132			];
133			const windows = this.platform === "win32";
134			try {
135				({ stdout } = await execFileAsync(
136					windows ? this.env.ComSpec || "cmd.exe" : "az",
137					windows ? ["/d", "/s", "/c", "az.cmd", ...args] : args,
138					{ env: this.env, timeout: this.timeoutMs },
139				));
140			} catch (error) {
141				throw new AxiError(
142					`No Azure DevOps credential: set ${PAT_ENV_VARS[0]} or sign in with \`az login\` (${error instanceof Error ? error.message : String(error)})`,
143					"VALIDATION_ERROR",
144					[`export ${PAT_ENV_VARS[0]}=<pat>`, "az login"],
145				);
146			}
147			const tokenResponse = parseJson<unknown>(stdout, "az access-token output");
148			if (
149				!isRecord(tokenResponse) ||
150				typeof tokenResponse.accessToken !== "string" ||
151				tokenResponse.accessToken.trim() === ""
152			) {
153				throw new AxiError(
154					"az returned no valid access token for Azure DevOps",
155					"VALIDATION_ERROR",
156				);
157			}
158			this.authHeader = `Bearer ${tokenResponse.accessToken.trim()}`;
159			return this.authHeader;
160		}
161	
162		private async request<T>(
163			path: string,
164			options: {
165				method?: string;
166				query?: Record<string, string | number | undefined>;
167				body?: unknown;
168				contentType?: string;
169			} = {},
170		): Promise<T> {
171			const query: Record<string, string> = { "api-version": API_VERSION };
172			for (const [key, value] of Object.entries(options.query ?? {})) {
173				if (value !== undefined && value !== "") query[key] = String(value);
174			}
175			const qs = new URLSearchParams(query).toString();
176			const url = `https://${this.host}/${enc(this.org)}${path}?${qs}`;
177			let authorization: string;
178			try {
179				authorization = await this.authorization();
180			} catch (error) {
181				throw definitive(error);
182			}
183			const signal = AbortSignal.timeout(this.timeoutMs);
184			let response: Response;
185			let text: string;
186			try {
187				response = await this.fetchImpl(url, {
188					method: options.method ?? "GET",
189					headers: {
190						Authorization: authorization,
191						Accept: "application/json",
192						...(options.body === undefined
193							? {}
194							: { "Content-Type": options.contentType ?? "application/json" }),
195					},
196					signal,
197					...(options.body === undefined
198						? {}
199						: { body: JSON.stringify(options.body) }),
200				});
201				text = await response.text();
202			} catch (error) {
203				if (signal.aborted) {
204					throw new AxiError(
205						`Azure DevOps request timed out after ${this.timeoutMs}ms`,
206						"UNKNOWN",
207					);
208				}
209				throw error;
210			}
211			if (!response.ok) {
212				throw adoError(response.status, text);
213			}
214			// Azure DevOps answers an unauthenticated REST call with 203 and an HTML
215			// sign-in page instead of a 401, so `response.ok` is true and the body is
216			// not JSON. Caught here, where every request routes through, so a bad or
217			// missing credential reads as an auth failure rather than a parse error.
218			if (response.status === 203 || /^\s*</.test(text)) {
219				throw definitive(
220					new AxiError(
221						"Azure DevOps rejected the credential (it returned a sign-in page)",
222						"VALIDATION_ERROR",
223						[
224							`export ${PAT_ENV_VARS[0]}=<pat> with Work Items (read & write) scope`,
225							"Or run `az login` for a bearer token",
226							`Check the org is spelled correctly: https://${this.host}/${enc(this.org)}`,
227						],
228					),
229				);
230			}
231			return (
232				text ? parseJson<T>(text, "Azure DevOps response") : undefined
233			) as T;
234		}
